drop policy if exists "anon submit business" on public.business_submissions;
create policy "public submit business safely" on public.business_submissions for insert to anon,authenticated with check (tenant_id is not null and exists(select 1 from public.tenants t where t.id=business_submissions.tenant_id) and status='pending' and reviewed_by is null and reviewed_at is null and review_notes is null and length(trim(business_name)) between 2 and 200 and length(trim(category)) between 2 and 120 and length(trim(city)) between 2 and 120 and length(trim(phone)) between 7 and 40 and consent_to_contact=true and source in('public_site','directory_listing_form'));
create policy "staff insert submissions" on public.business_submissions for insert to authenticated with check (tenant_id is not null and private.has_tenant_role(tenant_id,array['staff','admin','super_admin']::text[]) and status='pending' and reviewed_by is null and reviewed_at is null and review_notes is null);
